import { forwardRef, useRef } from 'react';
import { useTooltip, type TooltipProp } from '../../hooks/useTooltip';
import { useControllableState } from '../../hooks/useControllableState';

export interface ArvoIconButtonProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'type' | 'disabled'> {
  variant?: 'primary' | 'secondary' | 'tertiary' | 'outline' | 'danger';
  size?: 'xs' | 'sm' | 'md' | 'lg';
  type?: 'button' | 'submit' | 'reset';
  icon: string;
  /**
   * Optional alternate icon rendered when the button is selected. Use this for
   * outline/filled toggle pairs (e.g. `icon="bookmark-o"`, `selectedIcon="bookmark"`).
   * Falls back to `icon` when not provided.
   */
  selectedIcon?: string;
  /** Tooltip content. Doubles as the button's `aria-label` because the button is icon-only. */
  tooltip: TooltipProp;
  isDisabled?: boolean;
  /**
   * Selected (active) state.
   *
   * - When `isToggle` is `false` (default), parent-controlled active state
   *   (e.g. an active menu trigger). Click does NOT toggle the value.
   * - When `isToggle` is `true`, click toggles the state. Pass `isSelected` to
   *   make it controlled, or rely on `defaultSelected` for uncontrolled mode.
   */
  isSelected?: boolean;
  defaultSelected?: boolean;
  /** When true, click toggles the selected state and renders `aria-pressed`. */
  isToggle?: boolean;
  /** Fired when the toggle state flips. Only emitted when `isToggle` is true. */
  onSelectionChange?: (isSelected: boolean) => void;
  isLoading?: boolean;
}

const ArvoIconButton = forwardRef<HTMLButtonElement, ArvoIconButtonProps>(
  function ArvoIconButton(
    {
      variant = 'primary',
      size = 'md',
      type = 'button',
      icon,
      selectedIcon,
      tooltip,
      isDisabled = false,
      isSelected: selectedProp,
      defaultSelected = false,
      isToggle = false,
      onSelectionChange,
      isLoading = false,
      className,
      onClick,
      onKeyDown,
      ...rest
    },
    ref
  ) {
    const internalRef = useRef<HTMLButtonElement | null>(null);
    const tooltipContent = typeof tooltip === 'string' ? tooltip : tooltip.content;

    const [isSelected, setSelected] = useControllableState<boolean>(
      selectedProp,
      defaultSelected,
    );

    useTooltip({ triggerRef: internalRef, tooltip });

    const classes = [
      'arvo-icon-btn',
      `arvo-btn--${variant}`,
      `arvo-btn--${size}`,
      isLoading ? 'loading' : '',
      isSelected ? 'active' : '',
      className ?? '',
    ]
      .filter(Boolean)
      .join(' ');

    const blocked = isDisabled || isLoading;

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (blocked) {
        e.preventDefault();
        e.stopPropagation();
        return;
      }
      if (isToggle) {
        const next = !isSelected;
        setSelected(next);
        onSelectionChange?.(next);
      }
      onClick?.(e);
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLButtonElement>) => {
      if (blocked && (e.key === 'Enter' || e.key === ' ')) {
        e.preventDefault();
        e.stopPropagation();
        return;
      }
      onKeyDown?.(e);
    };

    const showAriaPressed = isToggle || selectedProp !== undefined;
    const ariaPressedProp = showAriaPressed ? { 'aria-pressed': isSelected } : {};

    const mergeRefs = (node: HTMLButtonElement | null) => {
      internalRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };

    const renderedIcon = isSelected && selectedIcon ? selectedIcon : icon;

    return (
      <button
        ref={mergeRefs}
        type={type}
        disabled={isDisabled}
        {...rest}
        className={classes}
        aria-label={tooltipContent}
        aria-busy={isLoading ? true : undefined}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        {...ariaPressedProp}
      >
        <span
          className={`arvo-btn__ico o9con o9con-${renderedIcon}`}
          aria-hidden="true"
        />
      </button>
    );
  }
);

export default ArvoIconButton;
export { ArvoIconButton };
